//! Generated files are fresh: each crate that writes a file into the repository (the reference
//! pages in `docs/reference/`, R33; the SDK's function and code lists, `formulas.md` 11 and
//! `diagnostics.md` 3) proves its committed copy equals what it would write now.
//!
//! A committed file whose first lines say `@generated by \`cargo run -p <crate> ...\`` while
//! `<crate>` declares no hook is a finding: the check skips only when nothing generated exists,
//! so it cannot pass vacuously beside files nothing proves fresh.
//!
//! The hook is declared, not discovered, so xtask needs no dependency on the engine crates and a
//! half-written crate cannot break its build. A crate declares in its `Cargo.toml`:
//!
//! ```toml
//! [package.metadata.via]
//! fresh = ["<bin>", "example:<name>"]
//! ```
//!
//! A plain name is run as `cargo run -q -p <crate> --bin <bin> -- --check`; `example:<name>` as
//! `cargo run -q -p <crate> --example <name> -- --check`, for a generator that should not ship
//! in the crate's binaries. The program exits 0 when every file it owns is fresh, and otherwise non-zero, naming each stale
//! file and the command that rewrites it on stderr.

use std::path::Path;
use std::process::Command;

use crate::report::{rel, CheckError, Outcome};

/// (package, program, manifest path) declared by workspace members, sorted.
fn hooks(root: &Path) -> Result<Vec<(String, String, String)>, CheckError> {
    let out = Command::new(std::env::var("CARGO").unwrap_or_else(|_| "cargo".to_string()))
        .args([
            "metadata",
            "--no-deps",
            "--format-version",
            "1",
            "--offline",
        ])
        .current_dir(root)
        .output()
        .map_err(|e| CheckError(format!("cannot run cargo metadata: {e}")))?;
    if !out.status.success() {
        return Err(CheckError(format!(
            "cargo metadata failed: {}",
            String::from_utf8_lossy(&out.stderr).trim()
        )));
    }
    let v: serde_json::Value = serde_json::from_slice(&out.stdout)
        .map_err(|e| CheckError(format!("cargo metadata output: {e}")))?;
    let mut found = Vec::new();
    for p in v["packages"].as_array().into_iter().flatten() {
        let name = p["name"].as_str().unwrap_or("").to_string();
        let manifest = p["manifest_path"].as_str().unwrap_or("").to_string();
        let fresh = &p["metadata"]["via"]["fresh"];
        if fresh.is_null() {
            continue;
        }
        let Some(bins) = fresh.as_array() else {
            return Err(CheckError(format!(
                "{manifest}: [package.metadata.via].fresh must be a list of bin names"
            )));
        };
        for b in bins {
            let bin = b.as_str().ok_or_else(|| {
                CheckError(format!(
                    "{manifest}: [package.metadata.via].fresh holds a non-string"
                ))
            })?;
            found.push((name.clone(), bin.to_string(), manifest.clone()));
        }
    }
    found.sort();
    Ok(found)
}

/// Where generated files may live; build output, the spike and virtual environments are not read.
const GENERATED_ROOTS: [&str; 5] = ["crates", "docs", "sdk", "spec", "tools"];
const SKIP_DIRS: [&str; 5] = ["target", ".git", ".venv", "node_modules", "__pycache__"];

/// The package a file's `@generated by \`cargo run -p <pkg> ...\`` header names, if any; only
/// the first five lines are read, where every generator writes its header.
pub fn generated_by(text: &str) -> Option<String> {
    text.lines().take(5).find_map(|l| {
        let rest = l.split_once("@generated by `cargo run")?.1;
        let mut it = rest.split_whitespace();
        while let Some(w) = it.next() {
            if w == "-p" || w == "--package" {
                return it.next().map(|p| p.trim_end_matches('`').to_string());
            }
        }
        None
    })
}

/// Every (repository path, package) of a file carrying a generated header, sorted.
fn generated_files(root: &Path) -> Result<Vec<(String, String)>, CheckError> {
    let mut out = Vec::new();
    let mut stack: Vec<std::path::PathBuf> = GENERATED_ROOTS
        .iter()
        .map(|d| root.join(d))
        .filter(|p| p.is_dir())
        .collect();
    while let Some(d) = stack.pop() {
        let entries =
            std::fs::read_dir(&d).map_err(|e| CheckError(format!("{}: {e}", d.display())))?;
        for e in entries.filter_map(Result::ok) {
            let p = e.path();
            let name = e.file_name();
            if p.is_dir() {
                if !SKIP_DIRS.iter().any(|s| name == *s) {
                    stack.push(p);
                }
            } else if let Ok(text) = std::fs::read_to_string(&p) {
                // Binary files fail to read as text and cannot carry the header; skipped.
                if let Some(pkg) = generated_by(&text) {
                    out.push((rel(root, &p), pkg));
                }
            }
        }
    }
    out.sort();
    Ok(out)
}

pub fn check(root: &Path) -> Result<Outcome, CheckError> {
    let mut o = Outcome::default();
    let hooks = hooks(root)?;
    // A committed generated file whose generator declares no hook is a finding, not a skip: the
    // check would otherwise pass while nothing it runs proves the file fresh.
    let generated = generated_files(root)?;
    for (path, pkg) in &generated {
        if !hooks.iter().any(|(p, _, _)| p == pkg) {
            o.finding(
                path.clone(),
                0,
                format!(
                    "generated by `{pkg}`, which declares no [package.metadata.via] fresh hook \
                     (add fresh = [\"example:<generator>\"] to its Cargo.toml; the generator must \
                     accept --check)"
                ),
            );
        }
    }
    if hooks.is_empty() {
        o.skipped = generated.is_empty();
        o.note(format!(
            "no crate declares [package.metadata.via] fresh = [...]; {} generated files found",
            generated.len()
        ));
        return Ok(o);
    }
    for (pkg, bin, manifest) in &hooks {
        let (flag, target) = match bin.strip_prefix("example:") {
            Some(e) => ("--example", e),
            None => ("--bin", bin.as_str()),
        };
        let out = Command::new(std::env::var("CARGO").unwrap_or_else(|_| "cargo".to_string()))
            .args(["run", "-q", "-p", pkg, flag, target, "--", "--check"])
            .current_dir(root)
            .output()
            .map_err(|e| CheckError(format!("cannot run cargo for {pkg}/{bin}: {e}")))?;
        if out.status.success() {
            o.note(format!("{pkg} {flag} {target}: fresh"));
        } else {
            o.finding(
                rel(root, Path::new(manifest)),
                0,
                format!(
                    "{flag} {target} --check reports stale or failed ({}): {}",
                    out.status,
                    String::from_utf8_lossy(&out.stderr).trim()
                ),
            );
        }
    }
    Ok(o)
}

#[cfg(test)]
mod tests {
    use super::generated_by;

    #[test]
    fn reads_generated_headers() {
        assert_eq!(
            generated_by(
                "<!-- @generated by `cargo run -p via-diag --example gen_reference` from x. -->\n"
            ),
            Some("via-diag".to_string())
        );
        assert_eq!(
            generated_by("// a\n// @generated by `cargo run -p via-expr --bin gen`.\n"),
            Some("via-expr".to_string())
        );
        assert_eq!(generated_by("// handwritten\n"), None);
        assert_eq!(
            generated_by("1\n2\n3\n4\n5\n// @generated by `cargo run -p late`\n"),
            None
        );
    }
}
